(()=>{const host=document.querySelector('[data-navigation]');if(!host)return;host.className='shared-navigation';const brand=document.createElement('a');brand.href='/';brand.className='shared-brand';brand.innerHTML='F↗ <span>FACTORY MANAGER</span>';const nav=document.createElement('nav');nav.setAttribute('aria-label','Navigation principale');for(const [href,name]of [['/','Explorateur'],['/calculateur','Calculateur'],['/design','Atelier'],['/creations','Créations']]){const a=document.createElement('a');a.href=href;a.textContent=name;if(location.pathname===href||(href==='/design'&&location.pathname==='/atelier')||(href==='/creations'&&location.pathname==='/creation'))a.setAttribute('aria-current','page');nav.append(a);}const local=document.createElement('span');local.className='shared-local';local.textContent='● Local';host.append(brand,nav,local);const themeLabel=document.createElement('label');themeLabel.className='theme-picker';themeLabel.textContent='Thème ';const theme=document.createElement('select');theme.id='themeChoice';theme.setAttribute('aria-label','Thème de l’interface');for(const [value,name]of [['green','Vert'],['orange','Orange FICSIT'],['dark','Dark'],['light','Light']]){const option=document.createElement('option');option.value=value;option.textContent=name;theme.append(option);}let chosen='green';try{const saved=localStorage.getItem('factoryTools.theme');if(['green','orange','dark','light'].includes(saved))chosen=saved;}catch{}document.documentElement.dataset.theme=chosen;theme.value=chosen;theme.onchange=()=>{document.documentElement.dataset.theme=theme.value;try{localStorage.setItem('factoryTools.theme',theme.value);}catch{}};themeLabel.append(theme);host.append(themeLabel);const languageLabel=document.createElement('label');languageLabel.className='language-picker';languageLabel.append(document.createTextNode('Langue '));const language=document.createElement('select');language.id='languageChoice';language.setAttribute('aria-label','Langue de l’interface');language.setAttribute('data-i18n-ignore','');for(const[value,name]of[['fr','Français'],['en','English']]){const option=document.createElement('option');option.value=value;option.textContent=name;option.lang=value;language.append(option);}language.value=FactoryI18n.language;language.onchange=async()=>{language.disabled=true;try{await FactoryI18n.setLanguage(language.value);}finally{language.disabled=false;}};languageLabel.append(language);host.append(languageLabel);})();
